package acme.v1;

message Good {
  string good_name = 1;
  int32 field_2 = 2;
  map<string, string> good_map = 3;
  oneof good_choice {
    string a = 4;
  }
}

message bad_message {
  string BadName = 1;
  map<string, string> BadMap = 2;
  oneof BadChoice {
    string b = 3;
    string C = 4;
  }
}

enum bad_enum {
  BAD_ENUM_UNSPECIFIED = 0;
  Bad_Value = 1;
}

service bad_service {
  rpc bad_call(Good) returns (Good);
}

